def compute(vars):
    values = [
        vars["v1"],
        vars["v2"],
        vars["v3"],
        vars["v4"],
        vars["v5"],
    ]
    threshold = 4000
    qualifying_years = [value for value in values if value > threshold]
    return {
        "value": len(qualifying_years),
        "trace": {
            "threshold": threshold,
            "qualifying_values": qualifying_years,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "years",
            },
        },
    }
